pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);

        // Alice deploys, so owner initially is address(this) (the test contract).
        // First, transfer ownership from test contract to Alice
        c.transferOwnership(alice);

        // Now Alice transfers ownership to Bob
        vm.prank(alice);
        c.transferOwnership(bob);

        // Assert that owner is now Bob
        assertEq(c.owner(), bob);
    }
}

